export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const bonus=p=>{const points=Math.max(0,Number(p)||0);return .12*(points/(points+3));};
export function effective(f,p=0,now=Date.now()) {const fatigue=f.fatigue||0;return f.stats.map((v,i)=>v*(1-Math.min(.25,(f.injuries||[]).filter(t=>t.until>now&&t.stat===i).reduce((a,t)=>a+t.penalty,0)))*(1-fatigue)*(1+bonus(p)));}
export function recover(f,now=Date.now()){f.injuries=f.injuries.filter(t=>t.until>now);const steps=Math.floor((now-f.restAt)/600000);if(steps>0){f.fatigue=Math.max(0,f.fatigue-steps*.05);f.restAt+=steps*600000;}}
export function healthy(f,now){return !f.injuries.some(t=>t.until>now&&t.severity==='Тяжёлая');}
export function event(a,b,sa,sb,pa,pb,now,rng=Math.random){let x=effective(a,pa,now),y=effective(b,pb,now);if(sa.energy<25)x=[x[0]*.85,x[1]*.85,x[2]];if(sb.energy<25)y=[y[0]*.85,y[1]*.85,y[2]];const side=rng()<x[1]/(x[1]+y[1])?0:1;const [atk,def,as,ds,ax,dx]=side===0?[a,b,sa,sb,x,y]:[b,a,sb,sa,y,x];as.energy-=5;ds.energy-=2;const hit=rng()<clamp(.6+.003*(ax[1]-dx[1]),.35,.8);let damage=0,injury=null;if(hit){damage=(4+rng()*4)*ax[0]/60;ds.hp=Math.max(0,ds.hp-damage);as.damage+=damage;if(rng()<(ds.hp<30?.02:.01)){const r=rng();const level=r<.8?0:r<.98?1:2;injury={severity:['Лёгкая','Средняя','Тяжёлая'][level],penalty:[.05,.1,.2][level],stat:Math.floor(rng()*3),until:now+[1800000,7200000,21600000][level]};def.injuries.push(injury);}}sa.energy=clamp(sa.energy+x[2]/30,0,100);sb.energy=clamp(sb.energy+y[2]/30,0,100);return {side,hit,damage,injury,stopped:ds.hp<=0||injury?.severity==='Тяжёлая'};}
